class _LandingPageState extends State<_LandingPage> {
  bool _failed = false;
  bool _redirecting = false;
  late final String _returnPath = safeReturnPath(widget.returnTo);

  @override
  void initState() {
    super.initState();
    if (cruftfreeRuntime.session.isAuthenticated) {
      _redirecting = true;
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) {
          GoRouter.of(context).go(_returnPath);
        }
      });
    }
  }

  Future<void> _signIn() async {
    setState(() => _failed = false);
    try {
      await cruftfreeRuntime.session.login();
    } on Object {
      if (mounted) {
        setState(() => _failed = true);
      }
      return;
    }
    if (mounted) {
      GoRouter.of(context).go(_returnPath);
    }
  }

  Widget _brand(AuthLandingBrand brand) {
    final name = cruftfreeRuntime.messages.key(brand.nameKey).text;
    final variants = brand.imageVariants;
    return CruftFreeBrand(
      label: name,
      image: variants == null ? null : ResponsiveImage(variants: variants),
      initials: variants == null ? cruftfreeRuntime.format.initials(name) : null,
    );
  }

  @override
  Widget build(BuildContext context) {
    if (_redirecting) {
      return const Scaffold(body: SizedBox.shrink());
    }
    if (_failed) {
      return _SignInFailed(onRetry: _signIn);
    }
    final messages = cruftfreeRuntime.messages;
    final brand = widget.landing.brand;
    return _AuthCard(
      children: [
        if (brand != null) _brand(brand),
        _heading(context, messages.key('framework.signInTitle').text),
        Text(messages.key('framework.signInSubtitle').text, textAlign: TextAlign.center),
        CruftFreeButton(label: messages.key('framework.signIn').text, kind: CruftFreeButtonKind.primary, onPressed: _signIn),
      ],
    );
  }
}

